import React, { forwardRef, useEffect, useRef, useState } from 'react';
import ReactMarkdown from 'react-markdown';
import { Components } from 'react-markdown/src/ast-to-react';
import rehypeWrap from 'rehype-wrap';
import gfm from 'remark-gfm';

import { tableMappings } from './transformers/table-mapping.js';
import { typographyMappings } from './transformers/typography-mapping.js';
import { wrapperMappings } from './transformers/wrapper-mapping.js';
import { findValidParent, findOffset, extractSourcePos } from './utils.js';

export interface MarkdownSelection {
  start: MarkdownSelectionPoint;
  end: MarkdownSelectionPoint;
}

export interface MarkdownSelectionPoint {
  line: number;
  column: number;
  offset: number;
}

export const componentMappings: Components = {
  ...typographyMappings,
  ...tableMappings,
};

export interface MarkdownProps {
  /** The markdown content itself. */
  children: string;
  onSelectionChange?: (selection: MarkdownSelection) => void;
}

/**
 * The `Markdown` component is a read-only way to display content formatted in
 * markdown-style.
 */
export const Markdown = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  MarkdownProps
>(({ children, onSelectionChange }, forwardedRef) => {
  const [mappings, setMappings] = useState<Components>(componentMappings);
  const startNode = useRef<Element | null>(null);
  const endNode = useRef<Element | null>(null);

  const handleSelectionChange = () => {
    const selection = document.getSelection();

    if (
      !selection ||
      selection.isCollapsed ||
      !selection.anchorNode ||
      !selection.focusNode
    ) {
      return;
    }

    const start = findValidParent(selection.anchorNode);
    const end = findValidParent(selection.focusNode);

    if (!start && !end) {
      return;
    }

    if (start) {
      startNode.current = start;
    }
    if (end) {
      endNode.current = end;
    }

    if (startNode.current && endNode.current) {
      const sourcePos = extractSourcePos(startNode.current, endNode.current);
      if (sourcePos && onSelectionChange) {
        const startOffset = findOffset(sourcePos.start, children as string, -1);
        const endOffset = findOffset(sourcePos?.end, children as string);
        sourcePos.start.offset = startOffset;
        sourcePos.end.offset = endOffset;

        onSelectionChange(sourcePos);
      }
    }
  };

  useEffect(() => {
    document.addEventListener('selectionchange', handleSelectionChange);

    return () => {
      document.removeEventListener('selectionchange', handleSelectionChange);
    };
  }, [children]);

  useEffect(() => {
    setMappings({
      ...componentMappings,
      ...wrapperMappings(forwardedRef),
    });
  }, [forwardedRef]);

  return (
    <ReactMarkdown
      components={mappings}
      remarkPlugins={[gfm as never]}
      skipHtml={true}
      rehypePlugins={[[rehypeWrap, { wrapper: 'div.wrapper' }]]}
      sourcePos
    >
      {children}
    </ReactMarkdown>
  );
});

(
  Markdown as typeof Markdown & {
    displayName: string;
  }
).displayName = 'Markdown';
